90: function shopItems(){if(currentTab==='base'){const index=state.bossActive?state.bossLevel:state.baseLevel-1;return state.bossActive||index<BASE_COSTS.length?[{id:'baseUpgrade',name:state.bossActive?'Defesa da Base':'Upgrade de Base',icon:state.bossActive?'⚠️':'🏙️',desc:state.bossActive?`${BOSSES[index].name} está atacando! Derrote-o antes que o tempo acabe.`:`Evolua para a Base nível ${state.baseLevel+1} e enfrente ${BOSSES[index].name}.`,baseCost:state.bossActive?state.bossCostPaid:BASE_COSTS[index],growth:1,base:true}]:[]}return DATA[currentTab]||[]}
