95: function missionReward(){return Math.max(5,Math.round((5+passive()*.45)*(1+Math.log10(1+state.totalEarned/1000)*.15)))}
96: function clickPower(){return 1+DATA.gear.filter(i=>i.click).reduce((s,i)=>s+count(i.id)*i.click,0)}
97: function repLevel(){return Math.max(1,Math.floor(Math.sqrt(state.totalEarned/250))+1)}
