function updateOccurrence(){const status=$('encounterStatus');if(state.minorBattle){status.textContent='OCORRÊNCIA EM COMBATE';status.classList.remove('ready');return}if(state.occurrenceReady){status.textContent='OCORRÊNCIA ATIVA · CLIQUE NO MAPA';status.classList.add('ready');return}const remaining=Math.max(0,(state.occurrenceAt-Date.now())/1000);status.textContent=`PRÓXIMA OCORRÊNCIA EM ${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(Math.floor(remaining%60)).padStart(2,'0')}`;status.classList.remove('ready')}
function startMinorEncounter(){if(!state.occurrenceReady||state.minorBattle||state.bossActive)return;state.minorBoss=Math.floor(Math.random()*MINOR_BOSSES.length);const boss=MINOR_BOSSES[state.minorBoss];state.minorBattle=true;state.occurrenceReady=false;state.occurrenceAt=0;state.minorBossHP=boss.hp;state.minorHeroHP=80;$('encounterFace').textContent=boss.face;$('encounterName').textContent=boss.name;$('diceResult').textContent='Role os dois d20 para iniciar.';$('rollDiceButton').disabled=false;render();notify(`${boss.name} · ameaça de rua!`);save()}
function finishMinorEncounter(won){state.minorBattle=false;state.occurrenceReady=false;state.occurrenceAt=Date.now()+OCCURRENCE_INTERVAL;$('rollDiceButton').disabled=true;if(won){const roll=Math.random();if(roll<.05){const hero=DATA.heroes.find(item=>item.id==='phoenix');state.counts.phoenix=count('phoenix')+1;notify(`RECOMPENSA LENDÁRIA: ${hero.icon} ${hero.name}!`)}else if(roll<.40){earn(10000);notify('RECOMPENSA: +10.000 CRÉDITOS!')}else{state.minorBuffUntil=Date.now()+120000;notify('RECOMPENSA: RENDA EM DOBRO POR 2 MINUTOS!')}popText('VITÓRIA!',window.innerWidth*.34,window.innerHeight*.4,true)}else{notify('A EQUIPE RECUOU. A próxima ocorrência virá em 20 minutos.');popText('DERROTA',window.innerWidth*.34,window.innerHeight*.4,true)}render();save()}
